#if UNITY_EDITOR
using System;
using System.Linq;
using System.Collections;
using System.Threading;
using System.Threading.Tasks;
using LastRail.Battle;
using Newtonsoft.Json.Linq;
using NUnit.Framework;
using UnityEngine.TestTools;
namespace LastRail.Tests.EditMode {
 public class BRefitConsumerTests {
  static JObject bundle;
  [OneTimeSetUp] public void PrivateIntake(){var raw=Environment.GetEnvironmentVariable("LASTRAIL_B_REFIT_PRIVATE");Environment.SetEnvironmentVariable("LASTRAIL_B_REFIT_PRIVATE",null);if(string.IsNullOrEmpty(raw))Assert.Ignore("Private actual refit TCP supervisor required");bundle=JObject.Parse(raw);}
  [OneTimeTearDown] public void Release(){bundle=null;}
  static BRefitHttpTransport Transport(string name)=>new BRefitHttpTransport(new BRefitPrivateIntake((JObject)bundle[name].DeepClone()));
  static IEnumerator Wait(Task task){while(!task.IsCompleted)yield return null;Assert.IsFalse(task.IsFaulted,"Safe refit exchange completes");Assert.IsFalse(task.IsCanceled);}
  static IEnumerator Finished(Task task){while(!task.IsCompleted)yield return null;}
  static JArray Cells()=>BRefitModelTests.Cells();
  static void Same(JToken a,JToken b)=>Assert.IsTrue(JToken.DeepEquals(a,b),"Original server result preserved");
  [UnityTest] public IEnumerator ActualReadSaveNoopReplayChangeAndOriginalReceiptKeepCurrentSeparate(){using var t=Transport("workflow");using var c=new BRefitController();using var conn=new BRefitConnection(c,t);c.Read();yield return Wait(conn.LastExchange);Assert.AreEqual(0,c.State.Revision);var original=c.Save(Cells(),"save");yield return Wait(conn.LastExchange);var ack=c.Receipt;Assert.AreEqual(1,(int)ack["revision"]);Assert.IsFalse((bool)ack["startReady"]);c.ReplayOriginal();yield return Wait(conn.LastExchange);Same(ack,c.Receipt);c.Read();yield return Wait(conn.LastExchange);Assert.AreEqual(1,c.State.Revision);c.Save(Cells(),"noop");yield return Wait(conn.LastExchange);Assert.IsFalse((bool)c.Receipt["changed"]);c.Read();yield return Wait(conn.LastExchange);var cells=Cells();cells[0]["type"]="BCB02";c.Save(cells,"change");yield return Wait(conn.LastExchange);c.Read();yield return Wait(conn.LastExchange);Assert.AreEqual(2,c.State.Revision);var current=c.State.Capture();var replay=t.SendAsync(original);yield return Wait(replay);Same(ack,replay.Result.Body);Same(current,c.State.Capture());Assert.AreEqual(0,t.InFlightCount);}
  [UnityTest] public IEnumerator ActualStaleRevisionAndHashConflictRequireGetAndNewKey(){using var t=Transport("conflict");var read=t.SendAsync(BRefitRequest.Read());yield return Wait(read);var zero=new BRefitSnapshot(read.Result.Body,"a");var first=t.SendAsync(BRefitRequest.Save(zero,Cells(),"first"));yield return Wait(first);using var c=new BRefitController();using var conn=new BRefitConnection(c,t);BRefitRequest requested=null;Action<BRefitRequest> command=r=>requested=r;c.Bind(command);c.Read();c.AcceptResponse(requested,read.Result);var stale=c.Save(Cells(),"stale");var response=t.SendAsync(stale);yield return Wait(response);Assert.AreEqual(409,response.Result.Status);c.AcceptResponse(stale,response.Result);Assert.Throws<InvalidOperationException>(()=>c.Save(Cells(),"premature"));c.Read();var fresh=t.SendAsync(requested);yield return Wait(fresh);c.AcceptResponse(requested,fresh.Result);Assert.Throws<InvalidOperationException>(()=>c.Save(Cells(),"stale"));var next=c.Save(Cells(),"fresh");var written=t.SendAsync(next);yield return Wait(written);c.AcceptResponse(next,written.Result);Assert.IsNotNull(c.Receipt);var altered=fresh.Result.Body;altered["sourceHash"]=new string('f',64);altered["eligibilityError"]="combat_b_refit_source_hash_conflict";var hash=t.SendAsync(BRefitRequest.Save(new BRefitSnapshot(altered,"a"),Cells(),"wrong-hash"));yield return Wait(hash);Assert.AreEqual(409,hash.Result.Status);Assert.AreEqual("combat_b_refit_source_hash_conflict",(string)hash.Result.Body["errorCode"]);}
  [UnityTest] public IEnumerator AccountsKeepIndependentRowsKeysAndSourceHashes(){using var a=Transport("accountA");using var b=Transport("accountB");var readA=a.SendAsync(BRefitRequest.Read());var readB=b.SendAsync(BRefitRequest.Read());yield return Wait(readA);yield return Wait(readB);var sa=new BRefitSnapshot(readA.Result.Body,"a");var sb=new BRefitSnapshot(readB.Result.Body,"b");Assert.AreNotEqual(sa.SourceHash,sb.SourceHash);var ra=a.SendAsync(BRefitRequest.Save(sa,Cells(),"same"));var rb=b.SendAsync(BRefitRequest.Save(sb,Cells(),"same"));yield return Wait(ra);yield return Wait(rb);Assert.AreEqual("a",(string)ra.Result.Body["refit"]["accountId"]);Assert.AreEqual("b",(string)rb.Result.Body["refit"]["accountId"]);Assert.AreNotEqual((string)ra.Result.Body["receiptId"],(string)rb.Result.Body["receiptId"]);var foreign=b.SendAsync(BRefitRequest.Save(sa,Cells(),"foreign"));yield return Finished(foreign);Assert.IsTrue(foreign.IsFaulted);Assert.AreEqual(0,b.InFlightCount);}
  [UnityTest] public IEnumerator LostAcknowledgementRetainsExactOriginalCommandAndRecoversActualCommittedRow(){using var t=Transport("lost");using var c=new BRefitController();using var conn=new BRefitConnection(c,t);c.Read();yield return Wait(conn.LastExchange);var original=c.Save(Cells(),"lost-key");yield return Wait(conn.LastExchange);Assert.AreEqual(503,c.LastError.Status);Assert.IsNull(c.Receipt);Assert.AreSame(original,c.OriginalRequest);Assert.Throws<InvalidOperationException>(()=>c.Save(Cells(),"new-key"));c.ReplayOriginal();yield return Wait(conn.LastExchange);var ack=c.Receipt;Assert.AreEqual(1,(int)ack["revision"]);c.Read();yield return Wait(conn.LastExchange);Assert.AreEqual(1,c.State.Revision);c.ReplayOriginal();yield return Wait(conn.LastExchange);Same(ack,c.Receipt);}
  [UnityTest] public IEnumerator RestoredSupplierUsesFreshAuthenticationAndOriginalPersistedReceipt(){using var fresh=Transport("restored");using var old=Transport("old");var rejected=old.SendAsync(BRefitRequest.Read());yield return Wait(rejected);Assert.AreEqual(401,rejected.Result.Status);var current=fresh.SendAsync(BRefitRequest.Read());yield return Wait(current);Assert.AreEqual(1,(int)current.Result.Body["revision"]);var original=BRefitRequest.Save(new BRefitSnapshot((JObject)bundle["preparedRead"],"a"),Cells(),"checkpoint");var replay=fresh.SendAsync(original);yield return Wait(replay);Same(bundle["preparedReceipt"],replay.Result.Body);Assert.AreEqual(0,fresh.InFlightCount);}
  [UnityTest] public IEnumerator RankChangesPreserveOldRefitAndOriginalReplayWithoutR5Issuance(){using var t=Transport("grown");var read=t.SendAsync(BRefitRequest.Read());yield return Wait(read);var state=new BRefitSnapshot(read.Result.Body,"a");Assert.AreEqual(2,state.RankRevision);Assert.IsNotNull(state.EligibilityError);Assert.AreEqual(1,(int)state.Refit["cars"][0]["rank"]);Assert.AreEqual(2,(int)state.Capture()["rankSource"]["ranks"][0]["rank"]);var request=BRefitRequest.Save(new BRefitSnapshot((JObject)bundle["preparedRead"],"a"),Cells(),"checkpoint");var replay=t.SendAsync(request);yield return Wait(replay);Same(bundle["preparedReceipt"],replay.Result.Body);}
  [UnityTest] public IEnumerator MissingCurrentSourceIsExplicit503ButOriginalReceiptStillReplays(){using var t=Transport("missing");var read=t.SendAsync(BRefitRequest.Read());yield return Wait(read);Assert.AreEqual(503,read.Result.Status);var replay=t.SendAsync(BRefitRequest.Save(new BRefitSnapshot((JObject)bundle["preparedRead"],"a"),Cells(),"checkpoint"));yield return Wait(replay);Same(bundle["preparedReceipt"],replay.Result.Body);}
  [UnityTest] public IEnumerator DisposeDuringExchangeCancelsOwnedWorkWithoutLatePublicationOrLosingOriginalCommand(){var t=Transport("slow");using var c=new BRefitController();var conn=new BRefitConnection(c,t);c.Read();yield return Wait(conn.LastExchange);var request=c.Save(Cells(),"cancelled");var pending=conn.LastExchange;yield return new UnityEngine.WaitForSecondsRealtime(.15f);conn.Dispose();yield return Finished(pending);Assert.IsTrue(pending.IsCanceled||pending.IsFaulted);Assert.IsNull(c.Receipt);Assert.AreSame(request,c.OriginalRequest);Assert.AreEqual(0,t.InFlightCount);using var reopened=Transport("slow");using var next=new BRefitConnection(c,reopened);c.ReplayOriginal();yield return Wait(next.LastExchange);Assert.AreEqual(1,(int)c.Receipt["revision"]);c.Read();yield return Wait(next.LastExchange);Assert.AreEqual(1,c.State.Revision);}
  [UnityTest] public IEnumerator RejectedAuthenticationStopsControllerAndNoMoreRequestsAreSent(){using var t=Transport("old");using var c=new BRefitController();using var conn=new BRefitConnection(c,t);c.Read();yield return Wait(conn.LastExchange);Assert.AreEqual(401,c.LastError.Status);Assert.Throws<InvalidOperationException>(()=>c.Read());Assert.Throws<InvalidOperationException>(()=>c.Save(Cells(),"no"));Assert.AreEqual(0,t.InFlightCount);}
  [UnityTest] public IEnumerator SameKeyConcurrentPostsShareOneResultAndChangedKeysCompeteOnOneRevision(){
   using var t=Transport("concurrent");var read=t.SendAsync(BRefitRequest.Read());yield return Wait(read);var state=new BRefitSnapshot(read.Result.Body,"a");var request=BRefitRequest.Save(state,Cells(),"duplicate");var first=t.SendAsync(request);var second=t.SendAsync(request);yield return Wait(Task.WhenAll(first,second));Assert.AreEqual(200,first.Result.Status);Same(first.Result.Body,second.Result.Body);
   var changed=Cells();changed[0]["type"]="BCB02";var conflict=t.SendAsync(BRefitRequest.Save(state,changed,"duplicate"));yield return Wait(conflict);Assert.AreEqual(409,conflict.Result.Status);Assert.AreEqual("idempotency_conflict",(string)conflict.Result.Body["errorCode"]);
   read=t.SendAsync(BRefitRequest.Read());yield return Wait(read);state=new BRefitSnapshot(read.Result.Body,"a");var other=Cells();other[0]["type"]="BCB03";var a=t.SendAsync(BRefitRequest.Save(state,changed,"changed-a"));var b=t.SendAsync(BRefitRequest.Save(state,other,"changed-b"));yield return Wait(Task.WhenAll(a,b));CollectionAssert.AreEquivalent(new[]{200,409},new[]{a.Result.Status,b.Result.Status});read=t.SendAsync(BRefitRequest.Read());yield return Wait(read);Assert.AreEqual(2,(int)read.Result.Body["revision"]);Assert.AreEqual(0,t.InFlightCount);
  }
 }
}
#endif